import{_ as o,o as i,c as a,ag as t}from"./chunks/framework.DJVIMu25.js";const u=JSON.parse('{"title":"游戏模式","description":"","frontmatter":{"title":"游戏模式"},"headers":[],"relativePath":"zh_Hans/guides/games.md","filePath":"zh_Hans/guides/games.md","lastUpdated":1786543805000}'),r={name:"zh_Hans/guides/games.md"};function e(n,l,s,g,h,c){return i(),a("div",null,[...l[0]||(l[0]=[t('<h1 id="游戏模式" tabindex="-1">游戏模式 <a class="header-anchor" href="#游戏模式" aria-label="Permalink to &quot;游戏模式&quot;">​</a></h1><p>JoyMart 内置 15 款游戏，全部集成在主 jar 中，无需额外模块。下面按单人、彩票/抽奖、各类小游戏、双人 / 多人对战分别介绍。各游戏的计分规则与特殊事件奖励见 <a href="./../reference/scoring">计分与事件</a>。</p><h2 id="单人游戏-2048-扫雷-打地鼠-宝石迷阵" tabindex="-1">单人游戏（2048 / 扫雷 / 打地鼠 / 宝石迷阵） <a class="header-anchor" href="#单人游戏-2048-扫雷-打地鼠-宝石迷阵" aria-label="Permalink to &quot;单人游戏（2048 / 扫雷 / 打地鼠 / 宝石迷阵）&quot;">​</a></h2><p>打开 <code>/gb</code> → 选择游戏 → 点击 <strong>开始游戏</strong> 即可。分数自动记录到高分榜。</p><h2 id="彩票-lottery" tabindex="-1">彩票（Lottery） <a class="header-anchor" href="#彩票-lottery" aria-label="Permalink to &quot;彩票（Lottery）&quot;">​</a></h2><p>经典数字型彩票，玩法完全在 GUI 中进行：</p><ol><li>打开 <code>/gb</code> → 选择 <strong>彩票</strong> → 选择 4 个数字（每位的范围 1–9）。</li><li>点击 <strong>开奖</strong> 按钮即可从奖项池中加权随机抽奖一次。</li><li>奖项池支持代币、金币（需 Vault）和控制台命令三种奖励，可同时下发。</li></ol><p><strong>配置奖项（管理员 GUI）：</strong></p><ul><li>入口：游戏内执行 <code>/gba games</code>，进入 <strong>彩票</strong> 管理页 → 点击 <strong>奖项池</strong> 按钮；或在 <code>lottery</code> 的管理 GUI 中点击奖项池图标。</li><li>在奖项池编辑界面可：增加新奖项、删除已有奖项、调整每个奖项的<strong>权重</strong>（越大越易抽中）、<strong>代币奖励</strong>、<strong>金币奖励</strong>与<strong>命令奖励</strong>。</li><li>改完点 <strong>保存</strong> 即写入 <code>plugins/JoyMart/games/lottery/config.yml</code>。</li></ul><p>奖项池的配置文件格式见 <a href="./configuration#奖项池配置">配置文件说明</a>。</p><h2 id="抽奖机-slotmachine" tabindex="-1">抽奖机（SlotMachine） <a class="header-anchor" href="#抽奖机-slotmachine" aria-label="Permalink to &quot;抽奖机（SlotMachine）&quot;">​</a></h2><p>经典拉霸机，3 格滚轮，点击拉杆后停在随机图案上：</p><ul><li>三个图案全相同 → 触发头奖（从对应奖项池加权抽取）</li><li>两个图案相同 → 触发小奖（按预设代币返还）</li><li>全不同 → 未中奖</li><li>奖项池配置方式与彩票完全一致（管理员 GUI 入口同理）。</li></ul><h2 id="迷宫-maze" tabindex="-1">迷宫（Maze） <a class="header-anchor" href="#迷宫-maze" aria-label="Permalink to &quot;迷宫（Maze）&quot;">​</a></h2><p>每局随机生成一个 9×9 的递归回溯法迷宫，玩家点击相邻格子即可向上下左右移动一格，目标是到达右下角终点：</p><ul><li>走过的路径会变绿色，方便回看。</li><li>计时器记录通关用时；用时越短，通关奖励代币越多。</li><li>中途关闭 GUI 视为放弃，无奖励。</li><li>通关后自动记录最佳用时到高分榜。</li></ul><h2 id="贪吃蛇-snake" tabindex="-1">贪吃蛇（Snake） <a class="header-anchor" href="#贪吃蛇-snake" aria-label="Permalink to &quot;贪吃蛇（Snake）&quot;">​</a></h2><p>经典贪吃蛇，在 9×5 的双箱界面中自动移动：</p><ul><li>点击方向按钮（上/下/左/右）控制蛇的移动方向，不能直接反向。</li><li>吃到食物（红苹果）蛇身变长并 +10 分，自动刷新新食物。</li><li>撞墙或咬到自身即游戏结束；填满整个棋盘视为通关。</li><li>支持暂停/继续按钮；分数越高代币奖励越多。</li></ul><h2 id="小恐龙跑酷-dinorun" tabindex="-1">小恐龙跑酷（DinoRun） <a class="header-anchor" href="#小恐龙跑酷-dinorun" aria-label="Permalink to &quot;小恐龙跑酷（DinoRun）&quot;">​</a></h2><p>灵感来自 Chrome 离线小恐龙，侧向滚动跑酷：</p><ul><li>恐龙自动向前奔跑，仙人掌从右侧滚入。</li><li>点击跳跃按钮（3 格宽，方便点击）跳过仙人掌。</li><li>每存活 1 tick +1 分；分数越高障碍物间隔越短（难度递增）。</li><li>撞到仙人掌即游戏结束；分数即存活时长。</li></ul><h2 id="国际象棋-chess" tabindex="-1">国际象棋（Chess） <a class="header-anchor" href="#国际象棋-chess" aria-label="Permalink to &quot;国际象棋（Chess）&quot;">​</a></h2><p>6×6 洛斯阿拉莫斯变体（无象），支持双人对战和 AI 对战：</p><ul><li>白方先行；玩家 1 执白（底部），玩家 2 / AI 执黑（顶部）。</li><li>棋子：车、马、后、王、马、车 + 6 个兵（无象）。</li><li>点击己方棋子选中（绿色高亮可走点），再点击目标格落子。</li><li>兵到达底线自动升变为后；支持将军/将杀/逼和判定。</li><li>认输按钮可随时结束；将杀对方即获胜。</li><li><strong>双人对战</strong>：邀请好友共享同一棋盘，轮流走棋。</li><li><strong>AI 对战</strong>：两步 minimax AI，会优先吃子、阻挡威胁、控制中心。</li></ul><h2 id="大富翁-monopoly" tabindex="-1">大富翁（Monopoly） <a class="header-anchor" href="#大富翁-monopoly" aria-label="Permalink to &quot;大富翁（Monopoly）&quot;">​</a></h2><p>经典桌游大富翁的 GUI 复刻，支持 <strong>2–3 人</strong> 同场对战，也支持 <strong>1 人 + AI</strong> 模式：</p><ul><li>26 格环形棋盘渲染在 6×9（54 格）箱子的外圈，中心为骰子、玩家信息与操作按钮。</li><li>格子类型：起点（GO，经过领 200 元）、监狱、免费停车、入狱；机会格与命运格随机抽卡；17 块可购买地产（老街、市政厅、火车站、机场、摩天大楼、金矿 等）。</li><li>每回合：当前玩家点击 <strong>掷骰</strong> → 单颗骰子前进相应步数 → 落在空地可购买、落在他人地盘自动扣租金、落在机会/命运格抽卡 → 点击 <strong>结束回合</strong>。</li><li>余额归零即破产淘汰，最后一名未破产的玩家获胜。</li><li><strong>3 人模式独有下注</strong>：开局前每个玩家可押注一名玩家，押中赢家可获额外奖励。</li><li><strong>AI 对手</strong>：单人进入即自动补一名 AI 玩家，AI 会自动购买地产、掷骰、结束回合。</li><li>奖励：胜 +10 代币、平 +3 代币、负 +2 代币。</li></ul><h2 id="双人游戏-井字棋-四子棋-石头剪刀布-战舰-国际象棋" tabindex="-1">双人游戏（井字棋 / 四子棋 / 石头剪刀布 / 战舰 / 国际象棋） <a class="header-anchor" href="#双人游戏-井字棋-四子棋-石头剪刀布-战舰-国际象棋" aria-label="Permalink to &quot;双人游戏（井字棋 / 四子棋 / 石头剪刀布 / 战舰 / 国际象棋）&quot;">​</a></h2><p>双人游戏提供两种对战方式：</p><ol><li><p><strong>邀请好友</strong> — 点击 <strong>邀请对战</strong>，在聊天中输入对方玩家名，对方会收到可点击的邀请消息（接受/拒绝）。接受后双方共享同一游戏界面，轮流操作。</p></li><li><p><strong>对战 AI</strong> — 点击 <strong>对战 AI</strong>，无需等待对手，立即开始。AI 会自动在 1 秒后出招：</p><ul><li><strong>井字棋 AI</strong>：策略型 — 先找自己能赢的位置 → 再封堵对手 → 优先占中心 → 占角 → 随机。</li><li><strong>四子棋 AI</strong>：策略型 — 先找自己能赢的列 → 再封堵对手 → 偏好中间列 → 随机。</li><li><strong>石头剪刀布 AI</strong>：随机出招。</li><li><strong>战舰 AI</strong>：随机射击未攻击过的格子。</li><li><strong>国际象棋 AI</strong>：两步 minimax — 评估每步走子后对手最佳回复，优先吃子、控制中心、阻挡威胁。</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">计入高分榜</p><p>对战 AI 的结果同样计入高分榜和代币奖励。</p></div>',32)])])}const p=o(r,[["render",e]]);export{u as __pageData,p as default};
